@@ -0,0 +1,61 @@
+package cache
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+func TestSimpleCache(t *testing.T) {
+	c := NewSimpleCache[int]()
+	if err := c.Add("permanent", 7); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("permanent"); err != nil || got != 7 {
+		t.Fatalf("Get permanent = %d, %v", got, err)
+	}
+	if err := c.AddWithTTL("short", 9, 20*time.Millisecond); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("short"); err != nil || got != 9 {
+		t.Fatalf("Get before expiry = %d, %v", got, err)
+	}
+	time.Sleep(30 * time.Millisecond)
+	if got, err := c.Get("short"); err == nil || got != 0 {
+		t.Fatalf("Get after expiry = %d, %v", got, err)
+	}
+	if keys := c.Keys(); len(keys) != 1 || keys[0] != "permanent" {
+		t.Fatalf("Keys after expiry = %v", keys)
+	}
+}
+
+func TestSimpleCacheLoader(t *testing.T) {
+	c := NewSimpleCache[string]()
+	loads := 0
+	loader := func(key string) (string, time.Duration, error) {
+		loads++
+		return key + "-value", 20 * time.Millisecond, nil
+	}
+	for i := 0; i < 2; i++ {
+		if got, err := c.GetWithLoader("item", loader); err != nil || got != "item-value" {
+			t.Fatalf("GetWithLoader = %q, %v", got, err)
+		}
+	}
+	if loads != 1 {
+		t.Fatalf("loader called %d times before expiry", loads)
+	}
+	time.Sleep(30 * time.Millisecond)
+	if _, err := c.GetWithLoader("item", loader); err != nil || loads != 2 {
+		t.Fatalf("loader after expiry: calls = %d, error = %v", loads, err)
+	}
+
+	wantErr := errors.New("load failed")
+	if got, err := c.GetWithLoader("missing", func(string) (string, time.Duration, error) {
+		return "ignored", time.Hour, wantErr
+	}); got != "" || err != wantErr {
+		t.Fatalf("failed loader = %q, %v", got, err)
+	}
+	if got, err := c.Get("missing"); got != "" || err == nil {
+		t.Fatalf("failed load was cached: %q, %v", got, err)
+	}
+}
